(async () => {
  const THREE = await import('three');
  const A = game.assets;
  const src = A.instances.find((i) => i.id === 'toro');
  const inst = A.build('toro', { ...src.layout, x: 10, z: 20 }, () => null);
  game.scene.add(inst.group);
  inst.group.position.set(10, 12.6, 20); inst.group.scale.setScalar(1.8);
  inst.group.updateMatrixWorld(true);
  const names = Object.keys(inst.parts);
  const box = (o) => new THREE.Box3().setFromObject(o);
  const centres = names.map((n) => ({ n, y: box(inst.parts[n]).getCenter(new THREE.Vector3()).y }));
  centres.sort((a, b) => a.y - b.y);
  const GAP = 0.34;
  centres.forEach((c, i) => { inst.parts[c.n].position.y += i * GAP; });
  inst.group.updateMatrixWorld(true);
  return { order: centres.map((c) => c.n), top: box(inst.group).max.y };
})()
